def prepare(root):
    output = dict(AUXILIARY)
    for relative, digest in EXPECTED.items():
        path = root / relative
        raw = path.read_bytes()
        if hashlib.sha256(raw).hexdigest() != digest:
            raise ValueError("Source differs from reviewed version: %s. No files changed; share this message." % relative)
        source = raw.decode("utf-8")
        for old, new in PATCHES[relative]:
            if source.count(old) != 1:
                raise ValueError("Expected one source anchor in " + relative)
            source = source.replace(old, new, 1)
        destination = relative.replace(".py", "_timed.py")
        output[destination] = source
    for relative, source in output.items():
        compile(source, relative, "exec")
        target = root / relative
        if target.exists() and (not target.is_file() or target.read_bytes() != source.encode("utf-8")):
            raise ValueError("Different destination already exists: %s. No files changed." % relative)
    return output


def install(root):
    output = prepare(root)
    created = []
    try:
        for relative, source in output.items():
            target = root / relative
            if target.exists():
                continue
            # Exclusive creation; never replace any original or existing file.
            with target.open("x", encoding="utf-8") as handle:
                created.append(target)
                handle.write(source)
    except BaseException:
        for target in reversed(created):
            target.unlink()
        raise
    print("Timing tools installed; original files unchanged. No trials were started.")
    for relative in output:
        print(root / relative)
    print("Timed results: " + str(root / "results/udp-timed-trials"))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project", type=Path, default=Path.home() / "green-fanet-multihop")
    args = parser.parse_args()
    try:
        install(args.project.expanduser().resolve())
    except (OSError, ValueError) as error:
        parser.exit(2, "Cannot install timing tools: %s\n" % error)


if __name__ == "__main__":
    main()
